{
  "summary": "The Clean Architecture audit reveals a critical breakdown across all core layers, with 6 major violations showing dependencies pointing outward rather than inward. The health score of 60.0 reflects fundamental architectural erosion where domain, application, and presentation layers improperly couple to infrastructure and presentation components, compromising testability, maintainability, and separation of concerns.",
  "rationales": [
    {
      "violation_id": "main->presentation.api",
      "why_it_matters": "Application-layer 'main' importing 'presentation.api' violates the inward-dependency rule—this flips the control flow and creates a cycle where higher layers dictate lower ones.",
      "prescribed_fix": "Create an Application-layer 'MainController' port/interface. Keep 'presentation.api.app' in Infrastructure as an adapter implementing that port. Inject at composition root via Dependency Injection."
    },
    {
      "violation_id": "main->infrastructure.database",
      "why_it_matters": "Application-layer 'main' reaching directly into 'infrastructure.database' bypasses the Domain/Application contract and hardcodes concrete implementations.",
      "prescribed_fix": "Define a 'DatabaseInitializer' port/interface inside the Application layer. Move 'init_db' logic to 'infrastructure.database' as an adapter implementing that port. Pass the adapter to 'main' via constructor/function injection."
    },
    {
      "violation_id": "domain.fraud_checker->infrastructure.database",
      "why_it_matters": "Domain-layer 'fraud_checker' depending on 'infrastructure.database' contaminates pure business entities with I/O concerns, making the domain untestable in isolation.",
      "prescribed_fix": "Introduce a 'FraudRepository' port/interface in the Domain layer. Implement it in 'infrastructure.database' as an adapter. Inject the interface into 'fraud_checker' at runtime to restore Dependency Inversion."
    },
    {
      "violation_id": "domain.payment_rule->presentation.controllers",
      "why_it_matters": "Domain-layer 'payment_rule' importing 'presentation.controllers' inverts the dependency arrow, forcing business logic to know about UI formatting and breaking layering.",
      "prescribed_fix": "Remove 'ResponseFormatter' import. Return plain domain DTOs from 'payment_rule'. Let 'presentation.controllers' handle formatting, implementing a 'PaymentPresenter' adapter if needed."
    },
    {
      "violation_id": "infrastructure.audit_logger->presentation.auth_middleware",
      "why_it_matters": "Infrastructure adapter for auditing reaching into 'auth_middleware' couples persistence concerns to HTTP/web primitives, violating adapter isolation.",
      "prescribed_fix": "Define an 'AuditContextProvider' port in the Application layer. Pass user/session data as parameters from 'auth_middleware' to 'audit_logger'. The middleware becomes the adapter supplying context."
    },
    {
      "violation_id": "presentation.order_routes->infrastructure.database",
      "why_it_matters": "Presentation routes skipping Application use-cases and hitting 'infrastructure.database' directly nullifies the architectural boundary, making testing and business rule enforcement impossible.",
      "prescribed_fix": "Create an 'OrderService' use-case in Application layer. Have 'order_routes' invoke that service instead of importing database. 'OrderService' coordinates between domain and repository ports."
    }
  ],
  "roadmap": [
    "P0 - Immediate: Refactor 'presentation.order_routes' and 'main' to route through Application use-cases/ports before any new feature development.",
    "P1 - Critical: Extract repository and initialization interfaces in Domain/Application layers; move concrete database code to Infrastructure adapters.",
    "P2 - High: Decouple 'infrastructure.audit_logger' from 'auth_middleware' by introducing a context-passing contract from Application layer."
  ]
}

